/**
 * Read len bytes at offset a from the master file(s) of a copy-on-write
 * export, i.e., ignoring the diff file.
 *
 * @param client The client we're serving for
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @return The number of bytes actually read (which may be less than len
 * when reading past the end of the master file), or -1 in case of an error.
 **/
static ssize_t cow_read_master(CLIENT *client, off_t a, char *buf, size_t len) {
	size_t done = 0;

	while(done < len) {
		int fhandle;
		off_t foffset;
		size_t maxbytes;
		ssize_t retval;

		if(get_filepos(client, a + done, &fhandle, &foffset, &maxbytes))
			return -1;
		size_t chunk = len - done;
		if(maxbytes && chunk > maxbytes)
			chunk = maxbytes;
		retval = pread(fhandle, buf + done, chunk, foffset);
		if (client->server->flags & F_TREEFILES) {
			close(fhandle);
		}
		if(retval <= 0) {
			if(retval < 0)
				return -1;
			break;
		}
		done += retval;
	}
	return done;
}
```

