/**
 * Read data from the master file(s) of an export, ignoring the diff
 * file. Used to implement copy-on-write.
 *
 * @param client The client we're serving for
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @return The number of bytes actually read (which may be less than
 * len when reading past the end of the master file), or -1 in case of
 * an error.
 **/
static ssize_t cow_read_master(CLIENT *client, off_t a, char *buf, size_t len) {
	size_t done = 0;

	while(done < len) {
		int fhandle;
		off_t foffset;
		size_t maxbytes;
		size_t chunk = len - done;
		ssize_t retval;

		if(get_filepos(client, a + done, &fhandle, &foffset, &maxbytes))
			return -1;
		if(maxbytes && chunk > maxbytes)
			chunk = maxbytes;
		retval = pread(fhandle, buf + done, chunk, foffset);
		if (client->server->flags & F_TREEFILES) {
			close(fhandle);
		}
		if(retval <= 0) {
			if(retval < 0)
				return -1;
			break;
		}
		done += retval;
	}
	return done;
}

/**
 * Read an amount of bytes at a given offset from a copy-on-write
 * export. Blocks that were written to during this session are read
 * back from the diff file; everything else comes from the master
 * file.
 *
 * @param client The client we're serving for
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t cow_read(CLIENT *client, off_t a, char *buf, size_t len) {
	size_t done = 0;

	pthread_rwlock_rdlock(&client->export_lock);
	while(done < len) {
		off_t pos = a + done;
		gint64 block = pos / DIFFPAGESIZE;
		size_t chunk = DIFFPAGESIZE - (pos % DIFFPAGESIZE);
		gint64 *doffset;
		ssize_t retval;

		if(chunk > len - done)
			chunk = len - done;
		doffset = g_hash_table_lookup(client->difmap, &block);
		if(doffset) {
			DEBUG("(COW READ from fd %d offset %llu len %u), ", client->difffile, (unsigned long long)(*doffset + (pos % DIFFPAGESIZE)), (unsigned int)chunk);
			retval = pread(client->difffile, buf + done, chunk,
					*doffset + (pos % DIFFPAGESIZE));
			if(retval != (ssize_t)chunk) {
				if(retval >= 0)
					errno = EIO;
				goto err;
			}
			done += chunk;
		} else {
			/* Extend the read over any consecutive clean
			 * blocks, so that we can serve them with a
			 * single read from the master file */
			while(done + chunk < len) {
				gint64 nextblock = (pos + chunk) / DIFFPAGESIZE;
				size_t step = DIFFPAGESIZE;

				if(g_hash_table_lookup(client->difmap, &nextblock))
					break;
				if(step > len - done - chunk)
					step = len - done - chunk;
				chunk += step;
			}
			retval = cow_read_master(client, pos, buf + done, chunk);
			if(retval < 0)
				goto err;
			done += retval;
			if(retval < (ssize_t)chunk)
				break;
		}
	}
	pthread_rwlock_unlock(&client->export_lock);
	return done;
err:
	pthread_rwlock_unlock(&client->export_lock);
	return -1;
}

/**
 * Write an amount of bytes at a given offset to the diff file of a
 * copy-on-write export. The master file is never modified; instead,
 * the blocks the write touches are copied up from the master file
 * into the diff file (if they were not copied up already), and the
 * written data is merged into them there.
 *
 * @param client The client we're serving for
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an
 * error
 **/
static ssize_t cow_write(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	size_t done = 0;
	int sparse = client->server->flags & F_SPARSE;

	pthread_rwlock_wrlock(&client->export_lock);
	while(done < len) {
		off_t pos = a + done;
		gint64 block = pos / DIFFPAGESIZE;
		size_t boffset = pos % DIFFPAGESIZE;
		size_t chunk = DIFFPAGESIZE - boffset;
		gint64 *doffset;

		if(chunk > len - done)
			chunk = len - done;
		doffset = g_hash_table_lookup(client->difmap, &block);
		if(doffset) {
			DEBUG("(COW WRITE to fd %d offset %llu len %u fua %d), ", client->difffile, (unsigned long long)(*doffset + boffset), (unsigned int)chunk, fua);
			if(pwrite(client->difffile, buf + done, chunk,
					*doffset + boffset) != (ssize_t)chunk)
				goto err;
		} else {
			char blk[DIFFPAGESIZE];
			gint64 newoffset;
			gint64 *key, *value;
			ssize_t retval;

			/* Copy up the current contents of the block */
			memset(blk, 0, sizeof blk);
			retval = cow_read_master(client, block * DIFFPAGESIZE,
					blk, DIFFPAGESIZE);
			if(retval < 0)
				goto err;
			memcpy(blk + boffset, buf + done, chunk);
			if(sparse) {
				/* In sparse mode, the diff file is as
				 * large as the export, and every block
				 * is stored at its own offset */
				newoffset = block * DIFFPAGESIZE;
				DEBUG("(COW WRITE to fd %d offset %llu len %u fua %d), ", client->difffile, (unsigned long long)newoffset, (unsigned int)DIFFPAGESIZE, fua);
				if(pwrite(client->difffile, blk, DIFFPAGESIZE,
						newoffset) != (ssize_t)DIFFPAGESIZE)
					goto err;
			} else {
				/* In non-sparse mode, every newly
				 * written block is mapped to the end
				 * of the diff file, preceded by the
				 * number of the block it contains */
				struct { uint64_t block; } header;

				header.block = block;
				newoffset = client->difffilelen + sizeof header;
				DEBUG("(COW WRITE to fd %d offset %llu len %u fua %d), ", client->difffile, (unsigned long long)newoffset, (unsigned int)DIFFPAGESIZE, fua);
				if(pwrite(client->difffile, &header, sizeof header,
						client->difffilelen) != (ssize_t)sizeof header)
					goto err;
				if(pwrite(client->difffile, blk, DIFFPAGESIZE,
						newoffset) != (ssize_t)DIFFPAGESIZE)
					goto err;
				client->difffilelen = newoffset + DIFFPAGESIZE;
			}
			key = g_new(gint64, 1);
			value = g_new(gint64, 1);
			*key = block;
			*value = newoffset;
			g_hash_table_insert(client->difmap, key, value);
		}
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	pthread_rwlock_unlock(&client->export_lock);
	return len;
err:
	pthread_rwlock_unlock(&client->export_lock);
	return -1;
}

